        }
    }
}

The factory is asked for three copies of one value and the result is printed with its size. What does the program print?

import java.util.List;
import java.util.Collections;

public class B14 {
    public static void main(String[] args) {
        List<String> list = Collections.nCopies(3, "z");
        System.out.println(list + " " + list.size());
    }
}

The comparison is by length rather than by alphabetical order. What does the program print?

import java.util.Arrays;
import java.util.List;
import java.util.Collections;

public class B15 {
    public static void main(String[] args) {
        List<String> words = Arrays.asList("a", "bbb");
        System.out.println(Collections.max(words, (x, y) -> x.length() - y.length()));
    }
}

The helper counts how many times a value appears. What does the program print?

import java.util.Arrays;
import java.util.List;
import java.util.Collections;

public class B16 {
    public static void main(String[] args) {
        List<String> list = Arrays.asList("a", "b", "a");
        System.out.println(Collections.frequency(list, "a"));
    }
}

The test asks whether the two lists have any value in common. What does the program print?

import java.util.Arrays;
import java.util.List;
import java.util.Collections;

public class B17 {
    public static void main(String[] args) {
        List<String> left = Arrays.asList("a", "b");
        List<String> right = Arrays.asList("b", "c");
        System.out.println(Collections.disjoint(left, right) ? "disjoint" : "shared");
    }
}

The shuffle is driven by a generator with a fixed seed, so the result is reproducible. What does the program print?

import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Random;

public class B18 {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("a", "b", "c", "d"));
        Collections.shuffle(list, new Random(7));
        System.out.println(list);
    }
}

Two values are pushed and then popped off, and the emptiness check is printed last. What does the program print?

import java.util.Deque;
import java.util.ArrayDeque;

public class B19 {
    public static void main(String[] args) {
        Deque<String> stack = new ArrayDeque<>();
        stack.push("p");
        stack.push("q");
        System.out.println(stack.pop() + "," + stack.pop() + "," + stack.isEmpty());
    }
}

One value handed to the deque is missing. What does the program print?

import java.util.ArrayDeque;

public class B20 {
    public static void main(String[] args) {
        try {
            new ArrayDeque<String>().add(null);
        } catch (RuntimeException e) {
            System.out.println(e.getClass().getSimpleName());
        }
    }
}

The deque is empty and the removal that reports emptiness by failing is used. What does the program print?

import java.util.ArrayDeque;

public class B21 {
    public static void main(String[] args) {
        try {
            new ArrayDeque<String>().pop();
        } catch (RuntimeException e) {
            System.out.println(e.getClass().getSimpleName());
        }
    }
}

The deque is empty and the removal that reports emptiness by handing back nothing is used. What does the program print?

import java.util.Deque;
import java.util.ArrayDeque;

public class B22 {
    public static void main(String[] args) {
        Deque<String> stack = new ArrayDeque<>();
        System.out.println(stack.poll() == null ? "nothing" : "something");
    }
}

Three words are queued with no comparison supplied, so the natural order decides. What does the program print?

import java.util.List;
import java.util.PriorityQueue;

public class B23 {
    public static void main(String[] args) {
        PriorityQueue<String> queue = new PriorityQueue<>();
        queue.addAll(List.of("pear", "apple", "fig"));
        System.out.println(queue.peek());
    }
}

The comparison has been turned upside down, so the queue now considers the largest value to be the first one out. What does the program print?

import java.util.List;
import java.util.Comparator;
import java.util.PriorityQueue;

public class B24 {
    public static void main(String[] args) {
        PriorityQueue<Integer> queue = new PriorityQueue<>(Comparator.reverseOrder());
        queue.addAll(List.of(3, 9, 1));
        System.out.println(queue.peek());
    }
}

The queue is copied into a list and compared with the ascending order. What does the program print?

import java.util.List;
import java.util.ArrayList;
import java.util.PriorityQueue;

public class B25 {
    public static void main(String[] args) {
        PriorityQueue<Integer> queue = new PriorityQueue<>();
        queue.addAll(List.of(5, 1, 3));
        List<Integer> seen = new ArrayList<>(queue);
        System.out.println(seen.equals(List.of(1, 3, 5)) ? "sorted" : "unsorted");
    }
}

The queue has never received a value and is asked for its head without removing. What does the program print?

import java.util.PriorityQueue;

public class B26 {
    public static void main(String[] args) {
        PriorityQueue<String> queue = new PriorityQueue<>();
        System.out.println(queue.peek() == null ? "empty" : "full");
    }
}

One key is present and one is not, and the lookup supplies a fallback for the missing one. What does the program print?

import java.util.Map;
import java.util.HashMap;

public class B27 {
    public static void main(String[] args) {
        Map<String, Integer> counts = new HashMap<>();
        counts.put("a", 1);
        System.out.println(counts.getOrDefault("b", -1));
    }
}

The key already holds 2, and a conditional put offers 9 for it. What does the program print?

import java.util.Map;
import java.util.HashMap;

public class B28 {
    public static void main(String[] args) {
        Map<String, Integer> counts = new HashMap<>();
        counts.put("a", 2);
        System.out.println(counts.putIfAbsent("a", 9) + " " + counts.get("a"));
    }
}

The key is missing, so the supplied function is asked to build a value. What does the program print?

import java.util.Map;
import java.util.HashMap;

public class B29 {
    public static void main(String[] args) {
        Map<String, Integer> counts = new HashMap<>();
        System.out.println(counts.computeIfAbsent("a", k -> 7));
    }
}

The same key is offered 1 and then 5, and the combining function adds. What does the program print?

import java.util.Map;
import java.util.HashMap;

public class B30 {
    public static void main(String[] args) {
        Map<String, Integer> counts = new HashMap<>();
        counts.merge("a", 1, Integer::sum);
        counts.merge("a", 5, Integer::sum);
        System.out.println(counts.get("a"));
    }
}

One entry is stored under a missing key and one under an ordinary key. What does the program print?

import java.util.Map;
import java.util.HashMap;

public class B31 {
    public static void main(String[] args) {
        Map<String, Integer> counts = new HashMap<>();
        counts.put(null, 0);
        counts.put("a", 1);
        System.out.println(counts.size() + " " + counts.containsKey(null));
    }
}

The keys are put in the order c, a, b and the key set is printed. What does the program print?

import java.util.Map;
import java.util.LinkedHashMap;

public class B32 {
    public static void main(String[] args) {
        Map<String, Integer> scores = new LinkedHashMap<>();
        scores.put("c", 3);
        scores.put("a", 1);
        scores.put("b", 2);
        System.out.println(scores.keySet());
    }
}

The keys are kept in ascending order and a value between two of them is probed from both sides. What does the program print?

import java.util.NavigableMap;
import java.util.TreeMap;

public class B33 {
    public static void main(String[] args) {
        NavigableMap<Integer, String> m = new TreeMap<>();
        m.put(5, "e");
        m.put(1, "a");
        m.put(9, "i");
        System.out.println(m.floorKey(6) + " " + m.ceilingKey(6));
    }
}

A view of the map is taken for the keys that fall short of 9. What does the program print?

import java.util.NavigableMap;
import java.util.TreeMap;

public class B34 {
    public static void main(String[] args) {
        NavigableMap<Integer, String> m = new TreeMap<>();
        m.put(5, "e");
        m.put(1, "a");
        m.put(9, "i");
        System.out.println(m.headMap(9).keySet());
    }
}

Two equal but separately built strings are used as keys in both kinds of map. What does the program print?

import java.util.Map;
import java.util.HashMap;
import java.util.IdentityHashMap;

public class B35 {
    public static void main(String[] args) {
        String first = new String("x");
        String second = new String("x");
        Map<String, String> byValue = new HashMap<>();
        byValue.put(first, "one");
        byValue.put(second, "two");
        Map<String, String> byReference = new IdentityHashMap<>();
        byReference.put(first, "one");
        byReference.put(second, "two");
        System.out.println(byValue.size() + " " + byReference.size());
    }
}

Both lists hold the same two values but in opposite order. What does the program print?

import java.util.List;

public class B36 {
    public static void main(String[] args) {
        System.out.println(List.of("a", "b").equals(List.of("b", "a")) ? "same" : "different");
    }
}

Both lists hold the same two values in opposite order. What does the program print?

import java.util.List;

public class B37 {
    public static void main(String[] args) {
        System.out.println(List.of("a", "b").hashCode() == List.of("b", "a").hashCode() ? "same" : "different");
    }
}

Each list holds one inner list holding the same two numbers. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B38 {
    public static void main(String[] args) {
        List<List<Integer>> left = new ArrayList<>(List.of(new ArrayList<>(List.of(1, 2))));
        List<List<Integer>> right = new ArrayList<>(List.of(new ArrayList<>(List.of(1, 2))));
        System.out.println(left.equals(right) ? "same" : "different");
    }
}

A row built fresh on the spot is searched for inside a list of rows. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B39 {
    public static void main(String[] args) {
        List<List<Integer>> grid = new ArrayList<>(List.of(List.of(1, 2)));
        System.out.println(grid.contains(List.of(1, 2)) ? "found" : "missing");
    }
}

The list holds whole numbers and the search is for a value of a different numeric type. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B40 {
    public static void main(String[] args) {
        List<Integer> values = new ArrayList<>(List.of(1, 2));
        System.out.println(values.indexOf(1L));
    }
}

A value is inserted at position 1 of a two-element list. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B41 {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("a", "c"));
        list.add(1, "b");
        System.out.println(list);
    }
}

Two identical lists are given the two same-named removal calls. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B42 {
    public static void main(String[] args) {
        List<Integer> byIndex = new ArrayList<>(List.of(5, 20, 30));
        List<Integer> byValue = new ArrayList<>(List.of(5, 20, 30));
        byIndex.remove(1);
        byValue.remove(Integer.valueOf(5));
        System.out.println(byIndex + " | " + byValue);
    }
}

Every element is tested and the even ones are removed. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B43 {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(1, 2, 3, 4));
        list.removeIf(n -> n % 2 == 0);
