}

Two names refer to one list, and the sort is applied through one of them. What does the program print?

import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

public class B45 {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("pear", "apple"));
        List<String> same = list;
        list.sort(Comparator.naturalOrder());
        System.out.println(same);
    }
}

The words are ordered by how many letters they have, not alphabetically. What does the program print?

import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

public class B46 {
    public static void main(String[] args) {
        List<String> words = new ArrayList<>(List.of("fig", "apple", "kiwi"));
        words.sort(Comparator.comparingInt(String::length));
        System.out.println(words);
    }
}

The caller supplies the type of array to build. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B47 {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(1, 2));
        Integer[] result = list.toArray(new Integer[0]);
        System.out.println(result.getClass().getSimpleName());
    }
}

The copy is called with no array to build into. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B48 {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("a"));
        System.out.println(list.toArray().getClass().getSimpleName());
    }
}

An iterator is obtained, then the list is changed, then the iterator is walked. What does the program print?

import java.util.List;
import java.util.Iterator;
import java.util.concurrent.CopyOnWriteArrayList;

public class B49 {
    public static void main(String[] args) {
        List<String> list = new CopyOnWriteArrayList<>(List.of("a", "b"));
        Iterator<String> it = list.iterator();
        list.add("c");
        StringBuilder seen = new StringBuilder();
        while (it.hasNext()) {
            seen.append(it.next());
        }
        System.out.println(seen);
    }
}

The iterator returns the first element, which is then replaced through the iterator. What does the program print?

import java.util.List;
import java.util.ArrayList;
import java.util.ListIterator;

public class B50 {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("a", "b"));
        ListIterator<String> it = list.listIterator();
        it.next();
        it.set("A");
        System.out.println(list);
    }
}

A new outer list is built from an old one, and the inner list is then changed through the new one. What does the program print?

import java.util.List;
import java.util.ArrayList;

public class B51 {
    public static void main(String[] args) {
